// Package calc implements `app calc`, which evaluates 64-bit signed integer expressions, one per line of standard input.
// See the "calc" section of SPEC.md.
package calc

import "base:intrinsics"
import "core:bufio"
import "core:fmt"
import "core:os"
import "core:strconv"
import "core:strings"

// run is the entry point of the `calc` subcommand.
run :: proc() {
	input, read_err := os.read_entire_file(os.stdin, context.allocator)
	if read_err != nil {
		fmt.eprintln("app calc: reading standard input:", read_err)
		os.exit(1)
	}
	defer delete(input)

	w: bufio.Writer
	bufio.writer_init(&w, os.to_writer(os.stdout), 64 * 1024)
	defer bufio.writer_destroy(&w)

	ev: Evaluator
	defer evaluator_destroy(&ev)

	rest := string(input)
	for line in strings.split_iterator(&rest, "\n") {
		if is_blank(line) {
			continue
		}
		if value, ok := evaluate(&ev, line); ok {
			buf: [32]byte
			bufio.writer_write_string(&w, strconv.write_int(buf[:], value, 10))
		} else {
			bufio.writer_write_string(&w, "error")
		}
		bufio.writer_write_byte(&w, '\n')
	}

	if err := bufio.writer_flush(&w); err != nil {
		fmt.eprintln("app calc: writing standard output:", err)
		os.exit(1)
	}
}

// Operator is a pending operator on the evaluator's operator stack.
Operator :: enum u8 {
	Left_Paren,
	Negate,
	Add,
	Sub,
	Mul,
	Div,
	Rem,
}

// Evaluator holds the operand and operator stacks of an operator-precedence
// evaluator. It is iterative rather than recursive so that arbitrarily deep
// nesting cannot overflow the call stack; the stacks are reused across lines.
Evaluator :: struct {
	values:    [dynamic]i64,
	operators: [dynamic]Operator,
}

evaluator_destroy :: proc(ev: ^Evaluator) {
	delete(ev.values)
	delete(ev.operators)
}

// precedence reports the binding strength of an operator; higher binds tighter.
// Left_Paren has the lowest so that reductions never cross it.
precedence :: proc(op: Operator) -> int {
	switch op {
	case .Left_Paren: return 0
	case .Add, .Sub:  return 1
	case .Mul, .Div, .Rem: return 2
	case .Negate:     return 3
	}
	unreachable()
}

// evaluate computes the value of the expression in `line`, returning ok = false
// on any syntax error, division by zero or 64-bit overflow.
evaluate :: proc(ev: ^Evaluator, line: string) -> (result: i64, ok: bool) {
	clear(&ev.values)
	clear(&ev.operators)

	// The grammar alternates between expecting an operand (a number, '(' or
	// unary '-') and expecting an operator (a binary operator or ')').
	expect_operand := true
	i := 0
	for i < len(line) {
		c := line[i]
		switch {
		case c == ' ' || c == '\t':
			i += 1

		case expect_operand:
			switch c {
			case '-':
				append(&ev.operators, Operator.Negate)
				i += 1
			case '(':
				append(&ev.operators, Operator.Left_Paren)
				i += 1
			case '0'..='9':
				value: i64
				for i < len(line) && '0' <= line[i] && line[i] <= '9' {
					digit := i64(line[i] - '0')
					value = checked_mul(value, 10) or_return
					value = checked_add(value, digit) or_return
					i += 1
				}
				append(&ev.values, value)
				expect_operand = false
			case:
				return 0, false
			}

		case:
			op: Operator
			switch c {
			case '+': op = .Add
			case '-': op = .Sub
			case '*': op = .Mul
			case '/': op = .Div
			case '%': op = .Rem
			case ')':
				reduce(ev, 1) or_return
				if len(ev.operators) == 0 {
					return 0, false // unbalanced ')'
				}
				pop(&ev.operators) // the matching '('
				i += 1
				continue
			case:
				return 0, false
			}
			// Left associativity: apply pending operators of equal or higher precedence first.
			reduce(ev, precedence(op)) or_return
			append(&ev.operators, op)
			expect_operand = true
			i += 1
		}
	}

	if expect_operand {
		return 0, false // empty expression or missing operand
	}
	reduce(ev, 1) or_return
	if len(ev.operators) != 0 {
		return 0, false // unbalanced '('
	}
	assert(len(ev.values) == 1)
	return ev.values[0], true
}

// reduce applies operators from the top of the stack while their precedence is
// at least `min_precedence`.
reduce :: proc(ev: ^Evaluator, min_precedence: int) -> (ok: bool) {
	for len(ev.operators) > 0 {
		op := ev.operators[len(ev.operators) - 1]
		if precedence(op) < min_precedence {
			break
		}
		pop(&ev.operators)

		if op == .Negate {
			top := &ev.values[len(ev.values) - 1]
			top^ = checked_sub(0, top^) or_return
			continue
		}

		rhs := pop(&ev.values)
		lhs := &ev.values[len(ev.values) - 1]
		lhs^ = apply(op, lhs^, rhs) or_return
	}
	return true
}

// apply evaluates a binary operator with the overflow and division rules of SPEC.md.
apply :: proc(op: Operator, a, b: i64) -> (result: i64, ok: bool) {
	#partial switch op {
	case .Add: return checked_add(a, b)
	case .Sub: return checked_sub(a, b)
	case .Mul: return checked_mul(a, b)
	case .Div:
		if b == 0 || (a == min(i64) && b == -1) {
			return 0, false
		}
		return a / b, true
	case .Rem:
		if b == 0 {
			return 0, false
		}
		if b == -1 {
			return 0, true // the quotient may overflow, but the remainder is always 0
		}
		return a % b, true
	}
	unreachable()
}

checked_add :: #force_inline proc(a, b: i64) -> (i64, bool) {
	r, overflow := intrinsics.overflow_add(a, b)
	return r, !overflow
}

checked_sub :: #force_inline proc(a, b: i64) -> (i64, bool) {
	r, overflow := intrinsics.overflow_sub(a, b)
	return r, !overflow
}

checked_mul :: #force_inline proc(a, b: i64) -> (i64, bool) {
	r, overflow := intrinsics.overflow_mul(a, b)
	return r, !overflow
}

// is_blank reports whether a line holds only spaces and tabs.
is_blank :: proc(line: string) -> bool {
	for c in transmute([]byte)line {
		if c != ' ' && c != '\t' {
			return false
		}
	}
	return true
}

// Package lru implements `app lru`, which simulates an LRU cache driven by commands read from standard input.
// See the "lru" section of SPEC.md.
package lru

import "core:fmt"
import "core:os"
import "core:strconv"
import "core:strings"

// Node_Index identifies a slot in `Cache.nodes`. Slot `SENTINEL` is the head of the
// circular recency list: `nodes[SENTINEL].next` is the most recently used entry and
// `nodes[SENTINEL].prev` the least recently used one.
Node_Index :: distinct u32

SENTINEL :: Node_Index(0)

Node :: struct {
	key:   string,
	value: string,
	prev:  Node_Index,
	next:  Node_Index,
}

// Cache is an LRU cache whose keys and values are slices borrowed from the input buffer,
// so no per-command allocation happens beyond the map and node pool growth.
Cache :: struct {
	capacity: int,
	index:    map[string]Node_Index,
	nodes:    [dynamic]Node,
	free:     [dynamic]Node_Index,
}

cache_init :: proc(c: ^Cache, capacity: int, expected_keys: int, allocator := context.allocator) {
	reserve := min(capacity, expected_keys) + 1
	c.capacity = capacity
	c.index = make(map[string]Node_Index, reserve, allocator)
	c.nodes = make([dynamic]Node, 1, reserve + 1, allocator)
	c.free = make([dynamic]Node_Index, 0, 0, allocator)
	c.nodes[SENTINEL] = Node{prev = SENTINEL, next = SENTINEL}
}

cache_destroy :: proc(c: ^Cache) {
	delete(c.index)
	delete(c.nodes)
	delete(c.free)
}

@(private)
list_unlink :: #force_inline proc(c: ^Cache, i: Node_Index) {
	n := &c.nodes[i]
	c.nodes[n.prev].next = n.next
	c.nodes[n.next].prev = n.prev
}

@(private)
list_push_front :: #force_inline proc(c: ^Cache, i: Node_Index) {
	head := c.nodes[SENTINEL].next
	c.nodes[i].prev = SENTINEL
	c.nodes[i].next = head
	c.nodes[head].prev = i
	c.nodes[SENTINEL].next = i
}

@(private)
node_alloc :: proc(c: ^Cache, key, value: string) -> Node_Index {
	node := Node{key = key, value = value}
	if i, ok := pop_safe(&c.free); ok {
		c.nodes[i] = node
		return i
	}
	append(&c.nodes, node)
	return Node_Index(len(c.nodes) - 1)
}

@(private)
node_release :: proc(c: ^Cache, i: Node_Index) {
	list_unlink(c, i)
	delete_key(&c.index, c.nodes[i].key)
	c.nodes[i] = {}
	append(&c.free, i)
}

cache_set :: proc(c: ^Cache, key, value: string) {
	if i, ok := c.index[key]; ok {
		c.nodes[i].value = value
		list_unlink(c, i)
		list_push_front(c, i)
		return
	}

	if len(c.index) >= c.capacity {
		node_release(c, c.nodes[SENTINEL].prev)
	}
	i := node_alloc(c, key, value)
	c.index[key] = i
	list_push_front(c, i)
}

cache_get :: proc(c: ^Cache, key: string) -> (value: string, ok: bool) {
	i := c.index[key] or_return
	list_unlink(c, i)
	list_push_front(c, i)
	return c.nodes[i].value, true
}

cache_del :: proc(c: ^Cache, key: string) -> bool {
	i := c.index[key] or_return
	node_release(c, i)
	return true
}

cache_size :: proc(c: ^Cache) -> int {
	return len(c.index)
}

// run is the entry point of the `lru` subcommand.
run :: proc() {
	input, err := read_all(os.stdin)
	if err != nil {
		fmt.eprintln("app lru: reading standard input:", err)
		os.exit(1)
	}
	defer delete(input)

	out := simulate(string(input))
	defer delete(out)

	if _, werr := os.write(os.stdout, out); werr != nil {
		fmt.eprintln("app lru: writing standard output:", werr)
		os.exit(1)
	}
}

// read_all reads `f` until end of file. Unlike `os.read_entire_file_from_file`, it never trusts the
// size reported by `fstat`, which for pipes on some platforms is only the currently buffered amount.
read_all :: proc(f: ^os.File, allocator := context.allocator) -> (data: []byte, err: os.Error) {
	buf := make([]byte, 1 << 20, allocator) or_return
	n := 0
	for {
		if n == len(buf) {
			grown := make([]byte, 2 * len(buf), allocator) or_return
			copy(grown, buf)
			delete(buf, allocator)
			buf = grown
		}
		read, rerr := os.read(f, buf[n:])
		n += read
		if rerr == .EOF || (rerr == nil && read == 0) {
			return buf[:n], nil
		}
		if rerr != nil {
			delete(buf, allocator)
			return nil, rerr
		}
	}
}

// simulate runs the commands in `input` (capacity line first) and returns the produced output.
// Keys and values in the cache borrow from `input`, which must outlive the call.
simulate :: proc(input: string, allocator := context.allocator) -> []byte {
	rest := input
	first, _ := next_line(&rest)
	capacity, cap_ok := strconv.parse_int(strings.trim_space(first), 10)
	if !cap_ok || capacity < 1 {
		return nil
	}

	// Each command line is at least 4 bytes ("SIZE"), which bounds the number of distinct keys.
	expected_keys := len(rest) / 4 + 1

	cache: Cache
	cache_init(&cache, capacity, expected_keys, allocator)
	defer cache_destroy(&cache)

	out := strings.builder_make(0, len(rest) / 2 + 16, allocator)

	for line in next_line(&rest) {
		cmd, args := split_token(line)
		switch cmd {
		case "SET":
			key, value := split_token(args)
			cache_set(&cache, key, value)
		case "GET":
			key, _ := split_token(args)
			if value, ok := cache_get(&cache, key); ok {
				strings.write_string(&out, value)
			} else {
				strings.write_string(&out, "NULL")
			}
			strings.write_byte(&out, '\n')
		case "DEL":
			key, _ := split_token(args)
			strings.write_byte(&out, '1' if cache_del(&cache, key) else '0')
			strings.write_byte(&out, '\n')
		case "SIZE":
			strings.write_int(&out, cache_size(&cache))
			strings.write_byte(&out, '\n')
		}
	}

	return out.buf[:]
}

// next_line pops the next line from `rest`, without its terminator (`\n` or `\r\n`).
@(private)
next_line :: proc(rest: ^string) -> (line: string, ok: bool) {
	if len(rest) == 0 {
		return "", false
	}
	if i := strings.index_byte(rest^, '\n'); i >= 0 {
		line, rest^ = rest[:i], rest[i + 1:]
	} else {
		line, rest^ = rest^, ""
	}
	if len(line) > 0 && line[len(line) - 1] == '\r' {
		line = line[:len(line) - 1]
	}
	return line, true
}

// split_token splits `s` at its first space into the leading token and the remainder.
@(private)
split_token :: #force_inline proc(s: string) -> (token, rest: string) {
	if i := strings.index_byte(s, ' '); i >= 0 {
		return s[:i], s[i + 1:]
	}
	return s, ""
}

// Entry point of `app`: dispatches the first argument to a subcommand.
// Each subcommand lives in its own package under src/ and exposes `run`.
package main

import "core:fmt"
import "core:os"

import "calc"
import "lru"
import "wordfreq"

Subcommand :: struct {
	name: string,
	run:  proc(),
}

SUBCOMMANDS :: [?]Subcommand {
	{"wordfreq", wordfreq.run},
	{"lru",      lru.run},
	{"calc",     calc.run},
}

main :: proc() {
	if len(os.args) < 2 {
		usage()
		os.exit(2)
	}

	name := os.args[1]
	for cmd in SUBCOMMANDS {
		if cmd.name == name {
			cmd.run()
			return
		}
	}

	fmt.eprintfln("app: unknown subcommand %q", name)
	usage()
	os.exit(2)
}

usage :: proc() {
	fmt.eprintln("usage: app <subcommand>")
	fmt.eprintln("subcommands:")
	for cmd in SUBCOMMANDS {
		fmt.eprintfln("  %s", cmd.name)
	}
}

// Package wordfreq implements `app wordfreq`, which prints the 10 most frequent words read from standard input.
// See the "wordfreq" section of SPEC.md.
package wordfreq

import "core:mem/virtual"
import "core:os"
import "core:strconv"
import "core:strings"

// TOP_N is the maximum number of words reported.
TOP_N :: 10

// READ_CHUNK is the size of each read from standard input.
READ_CHUNK :: 256 * 1024

Entry :: struct {
	word:  string,
	count: int,
}

// Counter accumulates case-folded word counts. Words are interned in `arena`,
// so the map keys stay valid independently of the input buffer.
Counter :: struct {
	counts:  map[string]int,
	arena:   virtual.Arena,
	// A word cut off by the end of a read chunk, carried over to the next one.
	partial: [dynamic]byte,
}

// run is the entry point of the `wordfreq` subcommand.
run :: proc() {
	c: Counter
	counter_init(&c)
	defer counter_destroy(&c)

	count_stream(&c, os.stdin)

	top: [TOP_N]Entry
	n := top_entries(c.counts, top[:])
	write_entries(top[:n])
}

counter_init :: proc(c: ^Counter) {
	c.counts = make(map[string]int, 1 << 12)
	c.partial = make([dynamic]byte, 0, 64)
	_ = virtual.arena_init_growing(&c.arena)
}

counter_destroy :: proc(c: ^Counter) {
	delete(c.counts)
	delete(c.partial)
	virtual.arena_destroy(&c.arena)
}

// count_stream tokenizes everything readable from `f`. Read errors are
// treated like end of input: whatever was read so far is counted.
count_stream :: proc(c: ^Counter, f: ^os.File) {
	buf := make([]byte, READ_CHUNK)
	defer delete(buf)

	for {
		n, err := os.read(f, buf)
		if n > 0 {
			count_chunk(c, buf[:n])
		}
		if err != nil || n == 0 {
			break
		}
	}
	if len(c.partial) > 0 {
		add_word(c, c.partial[:])
		clear(&c.partial)
	}
}

// count_chunk lowercases `chunk` in place and counts every word in it. A word
// touching the end of the chunk may continue in the next one, so it is kept in
// `c.partial` instead of being counted.
count_chunk :: proc(c: ^Counter, chunk: []byte) {
	i := 0

	// Finish a word carried over from the previous chunk.
	if len(c.partial) > 0 {
		for i < len(chunk) && is_letter(chunk[i]) {
			i += 1
		}
		lower_in_place(chunk[:i])
		append(&c.partial, ..chunk[:i])
		if i == len(chunk) {
			return
		}
		add_word(c, c.partial[:])
		clear(&c.partial)
	}

	for i < len(chunk) {
		for i < len(chunk) && !is_letter(chunk[i]) {
			i += 1
		}
		start := i
		for i < len(chunk) && is_letter(chunk[i]) {
			i += 1
		}
		if start == i {
			break
		}
		word := chunk[start:i]
		lower_in_place(word)
		if i == len(chunk) {
			append(&c.partial, ..word)
		} else {
			add_word(c, word)
		}
	}
}

// add_word increments the count of the already-lowercased `word`, interning
// it on first sight.
add_word :: proc(c: ^Counter, word: []byte) {
	key_ptr, value_ptr, just_inserted, _ := map_entry(&c.counts, string(word))
	if just_inserted {
		key_ptr^ = strings.clone(string(word), virtual.arena_allocator(&c.arena))
	}
	value_ptr^ += 1
}

@(require_results)
is_letter :: #force_inline proc "contextless" (b: byte) -> bool {
	return (b | 0x20) - 'a' < 26
}

lower_in_place :: #force_inline proc "contextless" (word: []byte) {
	for &b in word {
		b |= 0x20
	}
}

// ranks_before reports whether `a` is ordered before `b`: higher count first,
// then word in ascending byte order.
@(require_results)
ranks_before :: proc "contextless" (a, b: Entry) -> bool {
	if a.count != b.count {
		return a.count > b.count
	}
	return a.word < b.word
}

// top_entries fills `out` with the highest-ranked entries of `counts`, in rank
// order, and returns how many were written. Runs in O(len(counts) * len(out)).
@(require_results)
top_entries :: proc(counts: map[string]int, out: []Entry) -> int {
	n := 0
	for word, count in counts {
		e := Entry{word, count}
		if n == len(out) {
			if !ranks_before(e, out[n - 1]) {
				continue
			}
		} else {
			n += 1
		}
		// Insertion step: shift lower-ranked entries down to make room.
		j := n - 1
		for j > 0 && ranks_before(e, out[j - 1]) {
			out[j] = out[j - 1]
			j -= 1
		}
		out[j] = e
	}
	return n
}

write_entries :: proc(entries: []Entry) {
	if len(entries) == 0 {
		return
	}
	sb := strings.builder_make()
	defer strings.builder_destroy(&sb)

	num_buf: [32]byte
	for e in entries {
		strings.write_string(&sb, strconv.write_int(num_buf[:], i64(e.count), 10))
		strings.write_byte(&sb, ' ')
		strings.write_string(&sb, e.word)
		strings.write_byte(&sb, '\n')
	}
	_, _ = os.write(os.stdout, sb.buf[:])
}
